<script>
import {Button} from '$lib/components/ui/button';import {Badge} from '$lib/components/ui/badge';import {Input} from '$lib/components/ui/input';import {Progress} from '$lib/components/ui/progress';import * as Tabs from '$lib/components/ui/tabs';import {ArrowLeftRight,Plus,Search,History,Play,Settings2,Cloud,HardDrive} from '@lucide/svelte';
import FilePane from './FilePane.svelte';import {bytes,taskStatus} from './fileFormat.js';
let {files={},send}=$props();let tab=$state('transfer'),query=$state(''),editing=$state(false),draft=$state({});const act=command=>send('files',{command});
let mobilePane=$state('drive');
let shortcuts=$derived((files.recipes||[]).toReversed().filter(i=>[i.label,i.local_path,i.drive_id].join(' ').toLowerCase().includes(query.toLowerCase())));
let activeTasks=$derived((files.tasks||[]).filter(t=>['running','queued'].includes(t.status))),history=$derived((files.tasks||[]).filter(t=>!['running','queued'].includes(t.status)).toReversed());
</script>
<article class="files-workspace page-padding" aria-label="文件传输">
  <Tabs.Root class="files-root" bind:value={tab}><div class="files-tabs"><Tabs.List><Tabs.Trigger value="transfer"><ArrowLeftRight size={14}/>传输</Tabs.Trigger><Tabs.Trigger value="shortcuts">快捷复制</Tabs.Trigger><Tabs.Trigger value="history"><History size={14}/>传输记录</Tabs.Trigger></Tabs.List>{#if tab==='shortcuts'}<Button size="sm" onclick={()=>{draft={label:'',direction:'download',source_kind:'file',drive_id:'',local_path:'',enabled:true};editing=true;}}><Plus size={14}/>新增快捷操作</Button>{/if}</div>
  <Tabs.Content class="transfer-view" value="transfer"><nav class="file-pane-tabs" aria-label="文件位置"><Button variant={mobilePane==='drive'?'secondary':'ghost'} aria-pressed={mobilePane==='drive'} onclick={()=>mobilePane='drive'}><Cloud size={17}/>Google Drive<i class="status-dot" class:disconnected={!files.connected} aria-label={files.connected?'Drive 已连接':'Drive 连接待就绪'}></i></Button><Button variant={mobilePane==='local'?'secondary':'ghost'} aria-pressed={mobilePane==='local'} onclick={()=>mobilePane='local'}><HardDrive size={17}/>Molab</Button></nav><div class="transfer-panes">{#each ['drive','local'] as name}<div class="file-pane-slot" class:mobile-hidden={mobilePane!==name}><FilePane {name} pane={files.panes?.[name]||{}} target={files.panes?.[name==='drive'?'local':'drive']||{}} connected={files.connected} auth={files.drive_auth||{}} send={act}/></div>{/each}</div></Tabs.Content>
  <Tabs.Content value="shortcuts"><div class="shortcut-search"><Search size={16}/><Input aria-label="搜索快捷复制" placeholder="搜索名称或目录…" bind:value={query}/></div><div class="shortcut-grid">{#each shortcuts as item}<div class="surface shortcut-card"><div class="row"><ArrowLeftRight size={17}/><h3 title={item.source_kind==='directory'?'文件夹 · 本层文件':'文件'}>{item.label}</h3><Badge variant="secondary">{item.direction==='download'?'Drive → Molab':'Molab → Drive'}</Badge></div><p class="path-text">{item.local_path}</p><div class="row"><Button size="sm" disabled={!files.connected} onclick={()=>act({action:'replay',ids:[item.id]})}><Play size={13}/>复制</Button><Button size="sm" variant="outline" onclick={()=>{draft={...item};editing=true;}}><Settings2 size={13}/>管理</Button></div></div>{:else}<div class="empty-resource">暂无快捷操作</div>{/each}</div></Tabs.Content>
  <Tabs.Content value="history"><div class="surface transfer-history">{#each history as task}<div class="transfer-record"><div><strong>{task.name}</strong>{#if task.error}<p class="error-text">{task.error}</p>{/if}</div><Badge variant="secondary">{taskStatus[task.status]}</Badge>{#if ['failed','cancelled'].includes(task.status)&&task.retryable!==false}<Button size="sm" variant="outline" onclick={()=>act({action:'retry',task_id:task.id})}>重试</Button>{/if}<Button size="sm" variant="ghost" onclick={()=>act({action:'delete_task',id:task.id})}>删除记录</Button></div>{:else}<p class="empty-resource">暂无传输记录</p>{/each}</div></Tabs.Content>
  </Tabs.Root>
  {#if editing}<section class="surface shortcut-editor"><h2>快捷操作设置</h2><div class="parameter-grid"><label class="field"><span>名称</span><Input bind:value={draft.label}/></label><label class="field"><span>复制方向</span><select bind:value={draft.direction}><option value="download">Drive → Molab</option><option value="upload">Molab → Drive</option></select></label><label class="field"><span>内容</span><select bind:value={draft.source_kind}><option value="file">文件</option><option value="directory">文件夹 · 本层文件</option></select></label><label class="field"><span>Drive 文件或目录链接</span><Input bind:value={draft.drive_id}/></label><label class="field wide"><span>Molab 完整路径</span><Input bind:value={draft.local_path}/></label></div><div class="row"><Button onclick={()=>{act({action:'save_recipe',recipe:{...draft}});editing=false;}}>保存快捷操作</Button>{#if draft.id}<Button variant="destructive" onclick={()=>{act({action:'delete_recipe',id:draft.id});editing=false;}}>删除快捷操作</Button>{/if}<Button variant="ghost" onclick={()=>editing=false}>收起</Button></div></section>{/if}
  {#if files.error||files.message||files.notice||files.can_undo}<div class="file-notice" role="status"><span>{files.error||files.message||files.notice}</span>{#if files.can_undo}<Button variant="outline" size="sm" onclick={()=>act({action:'undo'})}>撤销删除</Button>{/if}</div>{/if}
  {#if activeTasks.length}<section class="transfer-queue"><h3>正在传输</h3>{#each activeTasks as task}<div class="surface transfer-task"><div class="row"><strong>{task.name}</strong><span>{bytes(task.bytes)} / {bytes(task.total)}{task.speed?' · '+bytes(task.speed)+'/s':''}</span><Button size="sm" variant="ghost" onclick={()=>act({action:'cancel',task_id:task.id})}>停止</Button></div><Progress max={task.total||1} value={task.bytes}/></div>{/each}</section>{/if}
</article>
